B.bwT=new A.dm("\u04e8\u043b\u0448\u0435\u043c\u0434\u0435\u0440 \u043c\u043c-\u0434\u0435\u043d \u043c\u0435\u0442\u0440\u0433\u0435 \u0431\u04e9\u043b\u0456\u043d\u0435\u0434\u0456 (\xf71000). \u04d8\u0440 \u0441\u0435\u043a\u0446\u0438\u044f \u2014 \u0436\u0435\u043a\u0435 \u043a\u043e\u0440\u043f\u0443\u0441: 2 \u0431\u04af\u0439\u0456\u0440 + \u04af\u0441\u0442\u0456/\u0430\u0441\u0442\u044b + \u0441\u04e9\u0440\u0435\u043b\u0435\u0440. \u0406\u0448\u043a\u0456 \u0435\u043d\u0456 = \u0435\u043d\u0456 \u2212 2 \xd7 \u043a\u043e\u0440\u043f\u0443\u0441 \u049b\u0430\u043b\u044b\u04a3\u0434\u044b\u0493\u044b. \u041a\u043e\u0440\u043f\u0443\u0441 \u043c\xb2 = 2\xd7\u0431\u0438\u0456\u043a\u0442\u0456\u043a\xd7\u0442\u0435\u0440\u0435\u04a3\u0434\u0456\u043a + (2+\u0441\u04e9\u0440\u0435)\xd7\u0456\u0448\u043a\u0456 \u0435\u043d\u0456\xd7\u0442\u0435\u0440\u0435\u04a3\u0434\u0456\u043a. \u0422\u0430\u0440\u0442\u043f\u0430\u0493\u0430 \u0431\u0438\u0456\u043a\u0442\u0456\u0433\u0456 150 \u043c\u043c \u049b\u043e\u0440\u0430\u043f\u0442\u044b\u04a3 4 \u0436\u0430\u0493\u044b \u043c\u0435\u043d \u0442\u04af\u0431\u0456 \u049b\u043e\u0441\u044b\u043b\u0430\u0434\u044b.\n\n\u049a\u0430\u0441\u0431\u0435\u0442 \u043f\u0435\u043d \u0430\u0440\u0442\u049b\u044b \u049b\u0430\u0431\u044b\u0440\u0493\u0430 = \u0435\u043d\u0456\xd7\u0431\u0438\u0456\u043a\u0442\u0456\u0433\u0456. \u049a\u0430\u0441\u0431\u0435\u0442 \u0430\u0443\u0434\u0430\u043d\u044b \u0442\u04b1\u0442\u0430\u0441 \u0436\u0430\u0431\u044b\u049b \u0434\u0435\u043f \u0430\u043b\u044b\u043d\u0430\u0434\u044b, \u0441\u0430\u04a3\u044b\u043b\u0430\u0443\u043b\u0430\u0440 \u0430\u043b\u044b\u043d\u0431\u0430\u0439\u0434\u044b; \u0435\u0441\u0456\u043a \u0441\u0430\u043d\u044b \u0442\u043e\u043f\u0441\u0430 \u043c\u0435\u043d \u0442\u04b1\u0442\u049b\u0430\u0493\u0430 \u04d9\u0441\u0435\u0440 \u0435\u0442\u0435\u0434\u0456. \u0416\u0438\u0435\u043a: \u0431\u04af\u0439\u0456\u0440\u043b\u0435\u0440\u0434\u0456\u04a3 \u0430\u043b\u0434\u044b\u04a3\u0493\u044b \u049b\u044b\u0440\u044b, \u043a\u04e9\u043b\u0434\u0435\u043d\u0435\u04a3 \u0431\u04e9\u043b\u0448\u0435\u043a\u0442\u0435\u0440\u0434\u0456\u04a3 \u0430\u043b\u0434\u044b\u04a3\u0493\u044b \u049b\u044b\u0440\u044b, \u049b\u0430\u0441\u0431\u0435\u0442 \u043f\u0435\u0440\u0438\u043c\u0435\u0442\u0440\u0456 \u0436\u04d9\u043d\u0435 \u0435\u0441\u0456\u043a\u0442\u0435\u0440 \u0430\u0440\u0430\u0441\u044b, \u0442\u0430\u0440\u0442\u043f\u0430 \u043f\u0435\u0440\u0438\u043c\u0435\u0442\u0440\u0456.\n\n\u0411\u04b1\u0440\u044b\u0448: \u0435\u043a\u0456\u043d\u0448\u0456 \u049b\u0430\u043d\u0430\u0442\u0442\u044b\u04a3 \u04b1\u0437\u044b\u043d\u0434\u044b\u0493\u044b\u043d \u0431\u0456\u0440\u0456\u043d\u0448\u0456 \u049b\u0430\u043d\u0430\u0442\u0442\u0430\u043d \u043a\u0435\u0439\u0456\u043d\u0433\u0456 \u0442\u0430\u0437\u0430 \u04b1\u0437\u044b\u043d\u0434\u044b\u049b\u043f\u0435\u043d \u0435\u043d\u0433\u0456\u0437\u0456\u04a3\u0456\u0437; \u0431\u04b1\u0440\u044b\u0448 \u0435\u043a\u0456 \u0440\u0435\u0442 \u049b\u043e\u0441\u044b\u043b\u043c\u0430\u0439\u0434\u044b. \u0410\u0440\u043d\u0430\u0439\u044b \u0431\u04b1\u0440\u044b\u0448 \u043c\u043e\u0434\u0443\u043b\u0456, \u043e\u0439\u044b\u049b, \u043e\u0440\u0442\u0430\u049b \u049b\u0430\u0431\u044b\u0440\u0493\u0430 \u043c\u0435\u043d \u043a\u0435\u0441\u0443 \u043a\u0430\u0440\u0442\u0430\u0441\u044b \u0435\u0441\u0435\u043f\u0442\u0435\u043b\u043c\u0435\u0439\u0434\u0456.\n\n\u0416\u04b1\u043c\u044b\u0441 \u04af\u0441\u0442\u0435\u043b\u0456 = \u0442\u04e9\u043c\u0435\u043d\u0433\u0456 \u043c\u043e\u0434\u0443\u043b\u044c\u0434\u0435\u0440 \u0435\u043d\u0456\xd7\u0442\u0435\u0440\u0435\u04a3\u0434\u0456\u0433\u0456, \u043f\u043e\u0433\u043e\u043d \u043c\u0435\u0442\u0440\u0434\u0435 = \u0435\u043d\u0434\u0435\u0440\u0456\u043d\u0456\u04a3 \u049b\u043e\u0441\u044b\u043d\u0434\u044b\u0441\u044b. \u041f\u0430\u043d\u0435\u043b\u044c \u0431\u0438\u0456\u043a\u0442\u0456\u0433\u0456 600 \u043c\u043c. \u041f\u043b\u0438\u043d\u0442\u0443\u0441 = \u0442\u04e9\u043c\u0435\u043d\u0433\u0456 \u0435\u043d\u0434\u0435\u0440 \u049b\u043e\u0441\u044b\u043d\u0434\u044b\u0441\u044b. \u0422\u043e\u043f\u0441\u0430: \u0435\u0441\u0456\u043a \u0431\u0438\u0456\u043a\u0442\u0456\u0433\u0456 \u22641 \u043c \u2014 2, \u22642 \u043c \u2014 3, >2 \u043c \u2014 4. \u04d8\u0440 \u0442\u04e9\u043c\u0435\u043d\u0433\u0456 \u043a\u043e\u0440\u043f\u0443\u0441\u049b\u0430 4 \u0430\u044f\u049b, \u0441\u0435\u043a\u0446\u0438\u044f\u0493\u0430 1 \u0431\u0435\u043a\u0456\u0442\u043a\u0456\u0448 \u0436\u0438\u044b\u043d\u0442\u044b\u0493\u044b. \u0428\u0442\u0430\u043d\u0433\u0430 = \u0448\u043a\u0430\u0444 \u0441\u0435\u043a\u0446\u0438\u044f\u043b\u0430\u0440\u044b\u043d\u044b\u04a3 \u0456\u0448\u043a\u0456 \u0435\u043d\u0456. \u0411\u0430\u0493\u044b\u0442\u0442\u0430\u0443\u044b\u0448 \u0436\u04b1\u0431\u044b = \u0442\u0430\u0440\u0442\u043f\u0430 \u0441\u0430\u043d\u044b; \u049b\u043e\u0441\u044b\u043c\u0448\u0430 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u04d9\u0434\u0435\u043f\u043a\u0456\u0434\u0435 0 (\u049b\u0430\u0439\u0442\u0430 \u0435\u0441\u0435\u043f\u0442\u0435\u043c\u0435\u04a3\u0456\u0437). \u0416\u044b\u043b\u0436\u044b\u043c\u0430\u043b\u044b \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u04d9\u0440 \u049b\u0430\u043d\u0430\u0442\u049b\u0430 1 \u0436\u0438\u044b\u043d\u0442\u044b\u049b.\n\n\u041c\u0430\u0442\u0435\u0440\u0438\u0430\u043b \u049b\u043e\u0440\u044b \u0442\u0435\u043a \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b \u043c\u04e9\u043b\u0448\u0435\u0440\u0456\u043d\u0435 \u049b\u043e\u043b\u0434\u0430\u043d\u044b\u043b\u0430\u0434\u044b. \u041f\u0430\u0440\u0430\u049b \u0441\u0430\u043d\u044b = \u0436\u043e\u0493\u0430\u0440\u044b\u0493\u0430 \u0434\u04e9\u04a3\u0433\u0435\u043b\u0435\u043a\u0442\u0435\u0443(\u043c\xb2\xd7(1+\u049b\u043e\u0440/100) \xf7 \u043f\u0430\u0440\u0430\u049b \u0430\u0443\u0434\u0430\u043d\u044b). \u0411\u04b1\u043b \u0428\u0410\u041c\u0410\u041c\u0415\u041d \u0435\u0441\u0435\u043f: \u0431\u04e9\u043b\u0448\u0435\u043a\u0442\u0435\u0440\u0434\u0456\u04a3 \u043e\u0440\u043d\u0430\u043b\u0430\u0441\u0443\u044b \u043c\u0435\u043d \u0442\u0430\u043b\u0448\u044b\u049b \u0431\u0430\u0493\u044b\u0442\u044b \u0442\u0435\u043a\u0441\u0435\u0440\u0456\u043b\u043c\u0435\u0439\u0434\u0456. \u0414\u0430\u043d\u0430 \u0431\u0456\u0440\u043b\u0456\u0433\u0456\u043d\u0434\u0435 \u043a\u043e\u0440\u043f\u0443\u0441 \u2014 \u043f\u0430\u043d\u0435\u043b\u044c\u0434\u0435\u0440 \u0441\u0430\u043d\u044b, \u049b\u0430\u0441\u0431\u0435\u0442 \u2014 \u0435\u0441\u0456\u043a\u0442\u0435\u0440 \u0441\u0430\u043d\u044b; \u04e9\u0437\u0433\u0435 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b \u2014 \u0441\u0435\u043a\u0446\u0438\u044f\u043b\u0430\u0440 \u0441\u0430\u043d\u044b. \u0416\u0438\u0435\u043a \u043f\u0435\u043d \u043f\u043b\u0438\u043d\u0442\u0443\u0441\u0442\u044b \u043c\xb2/\u043f\u0430\u0440\u0430\u049b\u043f\u0435\u043d \u0435\u0441\u0435\u043f\u0442\u0435\u043c\u0435\u04a3\u0456\u0437.\n\n\u049a\u043e\u043b\u043c\u0435\u043d \u043c\u04e9\u043b\u0448\u0435\u0440 \u0431\u0435\u0440\u0456\u043b\u0441\u0435, \u043e\u043b \u049b\u043e\u0440\u0434\u044b \u049b\u0430\u043c\u0442\u0438\u0442\u044b\u043d \u0441\u043e\u04a3\u0493\u044b \u043c\u04e9\u043b\u0448\u0435\u0440 \u0440\u0435\u0442\u0456\u043d\u0434\u0435 \u0430\u043b\u044b\u043d\u0430\u0434\u044b. \u041a\u0435\u0441\u0443, \u0436\u0438\u043d\u0430\u0443, \u0436\u0435\u0442\u043a\u0456\u0437\u0443, \u043e\u0440\u043d\u0430\u0442\u0443 \u2014 \u04d9\u0440\u049b\u0430\u0439\u0441\u044b\u0441\u044b \u0431\u0456\u0440 \u0436\u04b1\u043c\u044b\u0441; \u0436\u0438\u0435\u043a\u0442\u0435\u0443 \u2014 \u0442\u0430\u0437\u0430 \u0436\u0438\u0435\u043a \u04b1\u0437\u044b\u043d\u0434\u044b\u0493\u044b. \u0416\u0430\u043b\u043f\u044b \u04e9\u0437\u0456\u043d\u0434\u0456\u043a \u049b\u04b1\u043d = \u0431\u0430\u0440\u043b\u044b\u049b \u0436\u043e\u043b\u0434\u044b\u04a3 \u043c\u04e9\u043b\u0448\u0435\u0440\u0456 \xd7 \u0431\u0456\u0440\u043b\u0456\u043a \u0431\u0430\u0493\u0430\u0441\u044b. \u0421\u0430\u0442\u0443 = \u04e9\u0437\u0456\u043d\u0434\u0456\u043a \u049b\u04b1\u043d \xd7 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u2212 \u0431\u0456\u0440 \u0493\u0430\u043d\u0430 \u0436\u0435\u04a3\u0456\u043b\u0434\u0456\u043a. \u041f\u0430\u0439\u0434\u0430 = \u0441\u0430\u0442\u0443 \u2212 \u04e9\u0437\u0456\u043d\u0434\u0456\u043a \u049b\u04b1\u043d. \u0410\u049b\u0448\u0430 \u0442\u0438\u044b\u043d\u0493\u0430 \u0434\u0435\u0439\u0456\u043d \u0434\u04e9\u04a3\u0433\u0435\u043b\u0435\u043a\u0442\u0435\u043b\u0435\u0434\u0456.",null,null,null,null,null,null,null,null,null,null)
